        JavalinTest.test(app, (server, client) -> {
            var response = client.post("/reservations/1/check-in", "");
            assertEquals(200, response.code());

            var reservation = objectMapper.readValue(response.body().string(), Map.class);
            assertEquals("CHECKED_IN", reservation.get("status"));
        });
    }

    @Test
    @Order(11)
